package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;

import java.util.ArrayList;
import java.util.List;

/** A person's plan: a DRAFT claim of {@code amount} on the start date, then every {@code every} days, up to the end date;
 *  or, when {@code day} is 1 to 31 (and {@code every} 0), on that day of every month from the start's month (a day beyond
 *  the month's length on its last day), dates before the start left out. */
public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, int every, LocalDate end,
        int day) {

    public boolean monthly() {
        return day > 0;
    }

    /** The plan's dates up to and including {@code last}, in order. */
    public List<LocalDate> dates(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (monthly()) {
            for (LocalDate month = start.withDayOfMonth(1); !month.isAfter(last); month = month.plusMonths(1)) {
                LocalDate date = month.withDayOfMonth(Math.min(day, month.lengthOfMonth()));
                if (!date.isBefore(start) && !date.isAfter(last)) {
                    dates.add(date);
                }
            }
        } else {
            for (LocalDate date = start; !date.isAfter(last); date = date.plusDays(every)) {
                dates.add(date);
            }
        }
        return dates;
    }
}
package net.officefloor.hq.app.plan;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/** The store of the sheet's plans and of the dates each has made its claim for. */
@Repository
public class Plans {

    private final JdbcTemplate jdbc;

    public Plans(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's plans, in the order they were added. */
    public List<Plan> list(String sheetId) {
        return jdbc.query("SELECT id, sheet_id, person_id, amount, start_date, every_days, end_date, day_of_month FROM plan "
                + "WHERE sheet_id = ? ORDER BY id",
                (rs, n) -> new Plan(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                        rs.getBigDecimal("amount").setScale(2), rs.getDate("start_date").toLocalDate(),
                        rs.getInt("every_days"), rs.getDate("end_date").toLocalDate(), rs.getInt("day_of_month")),
                sheetId);
    }

    /** Adds the plan: the stored plan with its id. */
    public Plan add(Plan plan) {
        KeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO plan (sheet_id, person_id, amount, start_date, every_days, end_date, day_of_month) "
                    + "VALUES (?, ?, ?, ?, ?, ?, ?)", new String[] { "id" });
            ps.setString(1, plan.sheetId());
            ps.setLong(2, plan.personId());
            ps.setBigDecimal(3, plan.amount());
            ps.setDate(4, Date.valueOf(plan.start()));
            ps.setInt(5, plan.every());
